/* Keyboard-first counter workflow. Existing records remain compatible. */
db.cheques??=[];
let entryProduct='',entryQuery='',entryIndex=0,padNumber='',saleContact={phone:'',address:''},tender={cash:0,bank:0,cheque:0,number:'',bankName:'',date:''},returnCustomer='',returnQuery='';
const previousSaleSave=saveSale,previousReset=resetCart,previousReceipt=receipt,previousReturns=returnsView,previousView=view,previousCash=cashTotals,previousNewParty=newParty;
const roundMoney=n=>Math.round(Number(n)*100)/100;
const tenderTotal=t=>roundMoney(t.cash+t.bank+t.cheque);
function tenderFields(prefix='sale') {const t=prefix==='sale'?tender:{cash:0,bank:0,cheque:0,number:'',bankName:'',date:''};return `<div class="payment-grid">${[['cash','Cash'],['bank','Bank transfer'],['cheque','Cheque amount']].map(([k,l])=>`<div class="field"><label for="${prefix}-${k}">${l}</label><input id="${prefix}-${k}" type="number" min="0" step="0.01" value="${t[k]}" oninput="${prefix==='sale'?'updateTender()':''}"></div>`).join('')}</div><details ${t.cheque>0?'open':''} id="${prefix}-cheque-details"><summary>Cheque details</summary><div class="split">${field('Cheque number',prefix+'-number',t.number)}${field('Bank name',prefix+'-bankName',t.bankName)}${field('Cheque date',prefix+'-date',t.date,'date')}</div><p class="sub">Cheque stays pending until marked cleared. Pending cheques do not reduce the khata balance.</p></details>`}
function readTender(prefix){let result={};for(const k of ['cash','bank','cheque'])result[k]=Number($('#'+prefix+'-'+k).value);for(const k of ['number','bankName','date'])result[k]=$('#'+prefix+'-'+k).value.trim();return result}
function validTender(t){if(['cash','bank','cheque'].some(k=>!Number.isFinite(t[k])||t[k]<0)){toast('Enter valid non-negative amounts');return false}if(t.cheque>0&&(!t.number||!t.bankName||!t.date)){toast('Enter cheque number, bank and date');return false}return true}
function updateTender(){tender=readTender('sale');paid=roundMoney(tender.cash+tender.bank);$('#sale-cheque-details').open=tender.cheque>0;$('#tender-summary').innerHTML=tenderSummary()}
function tenderSummary(){return `<div class="summary-row"><span>Cash + bank received</span><strong>${money(tender.cash+tender.bank)}</strong></div><div class="summary-row"><span>Pending cheque</span><strong>${money(tender.cheque)}</strong></div><div class="summary-row"><span>Uncovered balance</span><strong>${money(Math.max(0,total()-tenderTotal(tender)))}</strong></div><p class="sub">Khata due until cheque clears: ${money(Math.max(0,total()-tender.cash-tender.bank))}</p>`}
function chooseCustomer(id){customer=id;const c=person('customers',id);saleContact={phone:c?.phone||'',address:c?.address||''};render()}
saleView=function(){let c=person('customers',customer);return head('New sale','Search → Enter → quantity → Enter → price → Enter',`<span class="pill">Draft · ${today()}</span>`)+`<div class="counter-layout"><div><div class="card pad"><div class="flex between"><h3>Customer & invoice</h3>${button('＋ New customer',"newParty('customers',true)",'small')}</div><div class="split"><div class="field"><label for="sale-customer">Customer / retailer</label><select id="sale-customer" onchange="chooseCustomer(this.value)">${options(db.customers,customer,'Walk-in customer')}</select></div>${field('Pad invoice number (optional)','pad-number',padNumber,'text','oninput="padNumber=this.value"')}</div><div class="split">${field('Phone number','sale-phone',saleContact.phone||c?.phone||'','tel','oninput="saleContact.phone=this.value"')}${field('Address','sale-address',saleContact.address||c?.address||'','text','oninput="saleContact.address=this.value"')}</div>${customer?`<div class="sub">Existing khata: ${money(customerBalance(customer))}</div>`:''}</div><section class="card pad section-gap"><h2>Add an item</h2><label for="item-search">Item name, article or colour</label><input id="item-search" class="wide" autocomplete="off" placeholder="Start typing an item name…" value="${esc(entryQuery)}" oninput="entryQuery=this.value;entryProduct='';entryIndex=0;entryResults()" onkeydown="entrySearchKey(event)"><div id="entry-results" class="entry-results"></div><div id="entry-selection">${entryProduct?selectionMarkup():''}</div><div class="entry-fields"><div class="field"><label for="entry-qty">Quantity</label><input id="entry-qty" type="number" min="1" step="1" value="1" onkeydown="if(event.key==='Enter'){event.preventDefault();$('#entry-price').focus();$('#entry-price').select()}"></div><div class="field"><label for="entry-price">Price per suit</label><input id="entry-price" type="number" min="0" step="0.01" value="${entryProduct?product(entryProduct).price:0}" onkeydown="if(event.key==='Enter'){event.preventDefault();addEntry()}"></div>${button('Add to cart →','addEntry()','primary')}</div><div class="sub">Use ↑ ↓ to choose a result. Enter moves to the next field.</div></section><section class="card pad section-gap"><h3>Payment · split across methods</h3>${tenderFields()}<div id="tender-summary">${tenderSummary()}</div><div class="field"><label for="sale-due">Due / cheque follow-up date</label><input id="sale-due" type="date" value="${dueDate}" onchange="dueDate=this.value"></div></section></div><aside class="card pad counter-cart"><div class="flex between"><h3>Current cart</h3>${badge(sum(cart.map(i=>i.qty))+' suits')}</div>${cart.length?cart.map((i,n)=>{let p=product(i.pid);return `<div class="cart-line"><div class="flex between"><strong>${esc(p.name)}</strong><button class="textbtn danger" aria-label="Remove ${esc(p.name)}" onclick="cart.splice(${n},1);render()">✕</button></div><div class="sub">${esc(p.color)} · ${esc(p.batch)}</div><div class="flex between"><span>${i.qty} × ${money(i.price)}</span><strong>${money(i.qty*i.price)}</strong></div>${button('Edit quantity / price',`editCartEntry(${n})`,'small')}</div>`}).join(''):'<div class="empty" style="padding:35px 5px">Your added items will appear here.</div>'}<div class="summary-row"><span>Subtotal</span><strong>${money(gross())}</strong></div><div class="field"><label for="discount">Discount</label><input id="discount" type="number" min="0" max="${gross()}" value="${discount}" onchange="discount=Math.max(0,Math.min(gross(),Number(this.value)||0));render()"></div><div class="summary-total"><span>Total bill</span><strong style="display:block">${money(total())}</strong></div>${button('Save & print bill →','saveSale()','primary wide')}<div class="flex section-gap">${button('Hold bill','holdOrder()','wide small')}${button('Clear','clearCart()','wide small')}</div></aside></div>`};
function entryMatches(){let q=entryQuery.trim().toLowerCase();return q?db.products.filter(p=>(p.name+' '+p.article+' '+p.color+' '+p.batch).toLowerCase().includes(q)).slice(0,12):[]}
function entryResults(){const matches=entryMatches();entryIndex=Math.min(entryIndex,Math.max(0,matches.length-1));$('#entry-results').innerHTML=matches.map((p,n)=>`<button class="entry-result ${n===entryIndex?'selected':''}" onmousedown="event.preventDefault()" onclick="selectEntry('${p.id}')"><strong>${esc(p.name)}</strong><span>${esc(p.color)} · ${esc(p.batch)} · ${p.stock-p.reserved} available · ${money(p.price)}</span></button>`).join('')||(entryQuery?'<p class="sub">No matching item.</p>':'');$('#entry-selection').innerHTML=''}
function entrySearchKey(e){const m=entryMatches();if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();entryIndex=(entryIndex+(e.key==='ArrowDown'?1:-1)+m.length)%Math.max(1,m.length);entryResults()}if(e.key==='Enter'){e.preventDefault();if(m[entryIndex])selectEntry(m[entryIndex].id);else toast('Choose a matching item first')}}
function selectionMarkup(){let p=product(entryProduct);return `<div class="note section-gap"><strong>${esc(p.name)}</strong><br>${esc(p.color)} · ${esc(p.batch)} · ${esc(sname(p.supplier))}<br>Available: ${p.stock-p.reserved} · Default price: ${money(p.price)}</div>`}
function selectEntry(id){entryProduct=id;entryQuery=product(id).name;$('#item-search').value=entryQuery;$('#entry-results').innerHTML='';$('#entry-selection').innerHTML=selectionMarkup();$('#entry-price').value=product(id).price;$('#entry-qty').focus();$('#entry-qty').select()}
function addEntry(){if(!entryProduct)return toast('Search and choose an item first');const qty=Number($('#entry-qty').value),price=Number($('#entry-price').value),p=product(entryProduct),existing=cart.find(i=>i.pid===p.id);if(!Number.isInteger(qty)||qty<1||!Number.isFinite(price)||price<0)return toast('Check quantity and price');if(qty+(existing?.qty||0)>p.stock-p.reserved+orderReservation(p.id))return toast('Not enough available stock');if(existing&&existing.price!==price)return toast('This batch is already in the cart. Use Edit to change its price.');if(existing)existing.qty+=qty;else cart.push({pid:p.id,qty,price});entryProduct='';entryQuery='';render();$('#item-search').focus();toast('Item added to cart')}
function editCartEntry(n){modal('Edit cart item',`<form id="edit-line" onsubmit="event.preventDefault();saveCartEdit(${n})">${field('Quantity','edit-qty',cart[n].qty,'number','min="1" step="1" required')}${field('Price','edit-price',cart[n].price,'number','min="0" step="0.01" required')}<button class="btn primary wide" type="submit">Update item</button></form>`)}
function saveCartEdit(n){const qty=Number($('#edit-qty').value),price=Number($('#edit-price').value),p=product(cart[n].pid);if(!Number.isInteger(qty)||qty<1||qty>p.stock-p.reserved+orderReservation(p.id)||!Number.isFinite(price)||price<0)return toast('Check quantity and price');cart[n]={...cart[n],qty,price};closeModal();render()}
resetCart=function(){previousReset();entryProduct='';entryQuery='';padNumber='';saleContact={phone:'',address:''};tender={cash:0,bank:0,cheque:0,number:'',bankName:'',date:''}};
saveSale=function(){tender=readTender('sale');if(!validTender(tender))return;if(tenderTotal(tender)>total())return toast('Combined payment exceeds the bill');if(padNumber.trim()&&db.sales.some(s=>s.padNumber?.toLowerCase()===padNumber.trim().toLowerCase()))return toast('This pad invoice number already exists');if(tender.cheque&&!customer)return toast('Choose a customer for cheque tracking');paid=roundMoney(tender.cash+tender.bank);method=tender.bank?'Split':'Cash';if(!validateCart())return;const saved={padNumber:padNumber.trim(),contact:{phone:$('#sale-phone').value,address:$('#sale-address').value},tender:structuredClone(tender)};const before=db.sales.length;previousSaleSave();if(db.sales.length===before)return;const s=db.sales[0];Object.assign(s,saved);if(saved.tender.cheque)db.cheques.unshift({id:uid('CHQ'),sale:s.id,party:s.customer,type:'customers',amount:saved.tender.cheque,number:saved.tender.number,bank:saved.tender.bankName,date:saved.tender.date,status:'Pending',created:today()});persist('Saved split payment '+s.id);receipt(s.id,true)};
receipt=function(id,success=false){previousReceipt(id,success);const s=db.sales.find(s=>s.id===id),el=$('.receipt'),c=s.contact||person('customers',s.customer)||{};el.insertAdjacentHTML('afterbegin',`<p><strong>Pad invoice: ${esc(s.padNumber||'—')}</strong><br>Phone: ${esc(c.phone||'—')}<br>Address: ${esc(c.address||'—')}</p>`);if(s.tender)el.insertAdjacentHTML('beforeend',`<hr><p>Cash: ${money(s.tender.cash)}<br>Bank transfer: ${money(s.tender.bank)}<br>Cheque tendered: ${money(s.tender.cheque)}</p>${db.cheques.filter(c=>c.sale===id).map(c=>`<p>Cheque ${esc(c.number)} · ${esc(c.bank)} · ${c.date}<br>Status: ${c.status}</p>`).join('')}`)};
newParty=function(type,fromSale=false){previousNewParty(type,fromSale);$('#party-form').insertAdjacentHTML('afterbegin',field('Address','address'))};
cashTotals=function(date){let result=previousCash(date);result.sales=sum(db.sales.filter(s=>s.date===date).map(s=>s.tender?s.tender.cash:s.method==='Cash'?s.paid:0));return result};
nav.splice(nav.findIndex(n=>n[0]==='expenses'),0,['cheques','▤','Cheque register']);
view=function(){return route==='cheques'?chequeView():previousView()};
function chequeView(){return head('Cheque register','Record clearance only after the bank confirms the transaction.')+`<div class="card">${table(['Cheque / bank','Customer / supplier','Bill','Amount','Date','Status',''],db.cheques.map(c=>`<tr><td>${esc(c.number)}<div class="sub">${esc(c.bank)}</div></td><td>${esc(person(c.type,c.party)?.name||'—')}</td><td>${esc(c.sale||c.reference||'Khata payment')}</td><td>${money(c.amount)}</td><td>${c.date}</td><td>${badge(c.status,c.status==='Pending'?'amber':'')}</td><td>${c.status==='Pending'?button('Record outcome',`chequeOutcome('${c.id}')`,'small'):esc(c.clearedDate||c.outcomeDate||'')}</td></tr>`))}</div>`}
function chequeOutcome(id){const c=db.cheques.find(c=>c.id===id);modal('Cheque outcome',`<p>${esc(c.number)} · ${money(c.amount)}</p>${selectField('Outcome','cheque-status','<option>Cleared</option><option>Bounced</option><option>Cancelled</option>')}${field('Transaction date','cheque-clear-date',today(),'date')}`,button('Save outcome',`saveChequeOutcome('${id}')`,'primary'))}
function saveChequeOutcome(id){const c=db.cheques.find(c=>c.id===id);if(!c||c.status!=='Pending')return;const status=$('#cheque-status').value,date=$('#cheque-clear-date').value;if(!date)return toast('Select transaction date');c.status=status;c.outcomeDate=date;if(status==='Cleared'){c.clearedDate=date;db.payments.unshift({id:uid('PAY'),type:c.type,party:c.party,amount:c.amount,date,method:'Cheque',note:'Cleared cheque '+c.number+(c.sale?' · '+c.sale:'')})}persist('Cheque '+c.number+': '+status);closeModal();render();toast(status==='Cleared'?'Cheque transaction recorded; khata updated':'Cheque outcome saved')}
paymentForm=function(type,id){modal(type==='customers'?'Receive payment':'Pay supplier',`<form id="payment-form" onsubmit="event.preventDefault();savePayment('${type}','${id}')"><p>${esc(person(type,id).name)}</p>${tenderFields('account')}${field('Payment date','account-date-paid',today(),'date','required')}${field('Reference / note','account-note')}<button class="btn primary wide" type="submit">Save transaction</button></form>`)};
savePayment=function(type,id){const t=readTender('account');if(!validTender(t)||!tenderTotal(t))return toast('Enter payment and complete cheque details');const date=$('#account-date-paid').value,note=$('#account-note').value;for(const [k,m]of [['cash','Cash'],['bank','Bank']])if(t[k])db.payments.unshift({id:uid('PAY')+'-'+k,type,party:id,amount:t[k],method:m,date,note});if(t.cheque)db.cheques.unshift({id:uid('CHQ'),type,party:id,amount:t.cheque,number:t.number,bank:t.bankName,date:t.date,status:'Pending',created:date,reference:note});persist('Split account payment: '+person(type,id).name);closeModal();render();toast('Transaction saved')};
returnsView=function(){if(returnBill)return returnDetail();return head('Customer returns','Choose the retailer, then search an item from their purchase history.')+`<div class="card pad"><div class="split"><div class="field"><label for="return-retailer">Retailer / customer</label><select id="return-retailer" onchange="returnCustomer=this.value;render()">${options(db.customers,returnCustomer,'Choose retailer')}</select></div><div class="field"><label for="return-item">Item name / article</label><input id="return-item" placeholder="Type the returned item name" value="${esc(returnQuery)}" oninput="returnQuery=this.value;renderReturnMatches()"></div></div><div id="return-matches">${returnMatchesMarkup()}</div></div><details class="card pad section-gap"><summary>Find by bill number instead</summary>${previousReturns()}</details>`};
function findReturnMatches(){if(!returnCustomer||!returnQuery.trim())return [];const q=returnQuery.toLowerCase().trim(),sales=db.sales.filter(s=>s.customer===returnCustomer).sort((a,b)=>b.date.localeCompare(a.date)||db.sales.indexOf(a)-db.sales.indexOf(b));return sales.flatMap(s=>s.items.filter(i=>{let p=product(i.pid);return (p.name+' '+p.article+' '+p.color).toLowerCase().includes(q)}).map(i=>({sale:s,item:i,p:product(i.pid),remaining:i.qty-returned(s.id,i.pid)})))}
function returnMatchesMarkup(){let list=findReturnMatches();if(!returnCustomer)return '<p class="sub">Choose the retailer to see only their purchases.</p>';if(!returnQuery.trim())return '<p class="sub">Enter an item name to find the latest matching bill.</p>';return table(['Item / batch','Original bill','Date','Net price','Returnable',''],list.map((r,n)=>`<tr><td><strong>${esc(r.p.name)}</strong><div class="sub">${esc(r.p.batch)} · ${esc(r.p.color)} · ${esc(sname(r.p.supplier))}</div>${n===0?badge('Latest matching purchase'):''}</td><td>${r.sale.id}<div class="sub">Pad: ${esc(r.sale.padNumber||'—')}</div></td><td>${r.sale.date}</td><td>${money(r.item.price*(1-r.sale.discount/sum(r.sale.items.map(i=>i.qty*i.price))))}</td><td>${r.remaining} / ${r.item.qty}</td><td>${r.remaining>0?button('Select return',`selectReturnMatch('${r.sale.id}','${r.p.id}')`,'small primary'):badge('Already returned','amber')}</td></tr>`))}
function renderReturnMatches(){$('#return-matches').innerHTML=returnMatchesMarkup();mobileTables($('#return-matches'))}
function selectReturnMatch(bill,pid){openReturn(bill);const s=db.sales.find(s=>s.id===bill),n=s.items.findIndex(i=>i.pid===pid),input=$('[name="q'+n+'"]');input.value=1;returnPreview();input.focus();input.select()}
document.addEventListener('input',e=>{const id=e.target.id;if(['sale-number','sale-bankName','sale-date'].includes(id))tender[id.slice(5)]=e.target.value});
const previousWorkflowRender=render;
render=function(){db.cheques??=[];previousWorkflowRender()};
let recoveryDraft={},recoveryDate=today();
const beforeRecoveryParties=partiesView,beforeRecoveryView=view;
partiesView=function(){let html=beforeRecoveryParties();return route==='customers'?html.replace('<div class="toolbar">',`<div class="toolbar">${button('Recovery All',"go('recovery')",'primary')}`):html};
view=function(){return route==='recovery'?recoveryView():beforeRecoveryView()};
function recoveryView(){return head('Recovery All','Naam ke saamne received amount likhein, phir sab ek saath save karein.',button('← Customer khata',"go('customers')"))+`<div class="card pad"><div class="field"><label for="recovery-date">Payment date</label><input id="recovery-date" type="date" value="${esc(recoveryDate)}" onchange="recoveryDate=this.value" required></div>${table(['Customer','Outstanding','Received amount','Payment method','Remaining'],db.customers.map((p,index)=>{const d=recoveryDraft[p.id]||{},balance=customerBalance(p.id);return `<tr><td><strong>${esc(p.name)}</strong><div class="sub">${esc(p.phone||'')}</div></td><td>${money(balance)}</td><td><input id="recovery-amount-${index}" aria-label="Received from ${esc(p.name)}" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0" value="${esc(d.amount||'')}" oninput="updateRecovery('${p.id}','amount',this.value)" onkeydown="if(event.key==='Enter'){event.preventDefault();document.getElementById('recovery-amount-${index+1}')?.focus()}" style="width:100%;min-width:100px"></td><td><select aria-label="Payment method for ${esc(p.name)}" onchange="updateRecovery('${p.id}','method',this.value)"><option ${d.method!=='Bank'?'selected':''}>Cash</option><option ${d.method==='Bank'?'selected':''}>Bank</option></select></td><td id="recovery-balance-${p.id}">${recoveryBalanceLabel(balance-Number(d.amount||0))}</td></tr>`}))}<div class="toolbar" style="justify-content:space-between;margin-top:20px"><strong id="recovery-total" aria-live="polite">${recoveryTotalLabel()}</strong>${button('Save all recoveries','saveRecoveries()','primary')}</div><p class="sub">Blank amounts are skipped. Extra payment becomes customer advance. Cheques can be recorded through the customer's Receive payment option.</p><div id="recovery-error" role="alert"></div></div>`}
function recoveryBalanceLabel(balance){return money(Math.abs(balance))+(balance<0?' advance':' due')}
function recoveryTotalLabel(){const amounts=Object.values(recoveryDraft).map(d=>Number(d.amount||0)).filter(n=>Number.isFinite(n)&&n>0);return money(sum(amounts))+' · '+amounts.length+' customers'}
function updateRecovery(id,key,value){recoveryDraft[id]??={amount:'',method:'Cash'};recoveryDraft[id][key]=value;$('#recovery-total').textContent=recoveryTotalLabel();$('#recovery-balance-'+id).textContent=recoveryBalanceLabel(customerBalance(id)-Number(recoveryDraft[id].amount||0));$('#recovery-error').textContent=''}
function saveRecoveries(){const fail=message=>{$('#recovery-error').textContent=message;return false};if(!/^\d{4}-\d{2}-\d{2}$/.test(recoveryDate)||!Number.isFinite(Date.parse(recoveryDate)))return fail('Choose a valid payment date.');const entries=[];for(const [id,d]of Object.entries(recoveryDraft)){if(d.amount===''||d.amount==null)continue;const amount=Number(d.amount);if(!Number.isFinite(amount)||amount<0||Math.abs(amount*100-Math.round(amount*100))>0.00001)return fail('Enter valid amounts with up to 2 decimal places.');if(!['Cash','Bank'].includes(d.method)||!db.customers.some(c=>c.id===id))return fail('Check the customer and payment method.');if(amount>0)entries.push({party:id,amount:Math.round(amount*100)/100,method:d.method})}if(!entries.length)return fail('Enter at least one received amount.');const batch=uid('REC');for(const e of entries)db.payments.unshift({...e,id:batch+'-'+e.party,type:'customers',date:recoveryDate,note:'Recovery All · '+batch});persist('Recovery All: '+entries.length+' customers · '+money(sum(entries.map(e=>e.amount))));recoveryDraft={};render();toast('Saved '+entries.length+' recoveries. Customer khatas updated.');return true}
render();

/* Outgoing supplier cheque details are captured at stock receiving too. */
const purchaseFormBeforeCheque=purchaseForm,purchaseSaveBeforeCheque=savePurchase,chequeViewBeforeDetails=chequeView;
purchaseForm=function(){purchaseFormBeforeCheque();const form=$('#purchase-form');if(form){form.innerHTML=form.innerHTML.replace(field('Payment to supplier','paid',0,'number','min="0" step="0.01"'),'<h3 class="section-gap">Payment to supplier</h3>'+tenderFields('purchase'))}}
savePurchase=function(){const t=readTender('purchase');if(!validTender(t))return;const totalCost=sum(purchaseLines.map(x=>x.qty*x.cost));if(tenderTotal(t)>totalCost)return toast('Combined supplier payment exceeds stock cost');const form=$('#purchase-form');if(form&&!form.innerHTML.includes('purchase-paid-hidden'))form.innerHTML+='<input id="purchase-paid-hidden" name="paid" type="hidden">';if($('#purchase-paid-hidden'))$('#purchase-paid-hidden').value=roundMoney(t.cash+t.bank);const before=db.purchases.length;purchaseSaveBeforeCheque();if(db.purchases.length===before)return;const pur=db.purchases[0];pur.tender=structuredClone(t);pur.paymentStatus=t.cheque?'Cheque pending':'Paid at receiving';if(t.cheque){db.cheques.unshift({id:uid('CHQ'),type:'suppliers',party:pur.supplier,amount:t.cheque,number:t.number,bank:t.bankName,date:t.date,status:'Pending',created:pur.date,reference:'Stock delivery '+pur.id});persist('Supplier cheque issued for '+pur.id);render();toast('Delivery saved. Cheque added to register')}};
chequeView=function(){return head('Cheque register','All customer and supplier cheques with their complete details.')+`<div class="card">${table(['Cheque / bank','Issued to','Amount','Cheque date','Recorded','Status','Purpose'],db.cheques.map(c=>`<tr><td><strong>${esc(c.number||'—')}</strong><div class="sub">${esc(c.bank||'—')}</div></td><td>${esc(person(c.type,c.party)?.name||'—')}<div class="sub">${c.type==='suppliers'?'Supplier':'Customer'}</div></td><td>${money(c.amount)}</td><td>${c.date||'—'}</td><td>${c.created||'—'}</td><td>${badge(c.status,c.status==='Pending'?'amber':'')}</td><td>${esc(c.sale||c.reference||'Khata payment')}</td></tr>`))}</div>`};
render();

/* Simple multi-line receiving and return adjustment flow. */
let purchaseLines=[],saleReturnLines=[],saleReturnCode='';
const previousPurchaseForm=purchaseForm,previousPurchaseSave=savePurchase,previousWorkflowSaleSave=saveSale;
function purchaseLineCode(line){return (line.supplier+'-'+line.batch+'-'+line.size).toUpperCase().replace(/[^A-Z0-9-]/g,'').slice(0,55)}
function purchaseLinesMarkup(){return `<div id="purchase-lines" class="purchase-preview"><div class="flex between"><h3>Added stock</h3>${badge(purchaseLines.length+' items')}</div>${purchaseLines.length?purchaseLines.map((x,n)=>`<div class="purchase-line"><div><strong>${esc(x.name||'Unnamed item')}</strong><div class="sub">${esc(x.batch)} · ${esc(x.size)} · ${x.qty} suits</div><div class="sub">${money(x.cost)} cost · ${money(x.price)} sale · ${esc(x.location)}</div></div><button type="button" class="textbtn danger" aria-label="Remove item ${n+1}" onclick="removePurchaseLine(${n})">✕</button></div>`).join(''):'<div class="empty purchase-empty">As you add stock, it will appear here.</div>'}${purchaseLines.length?`<div class="summary-row"><span>Total stock cost</span><strong>${money(sum(purchaseLines.map(x=>x.qty*x.cost)))}</strong></div>`:''}</div>`}
purchaseForm=function(){purchaseLines=[];modal('Receive a new delivery',`<form id="purchase-form" onsubmit="event.preventDefault();savePurchase()"><div class="purchase-layout"><div class="purchase-entry"><div class="split">${selectField('Supplier','supplier',options(db.suppliers))}${field('Arrival date','date',today(),'date','required')}</div>${field('Batch number','batch','','text','required placeholder="RCH-B05"')}${field('Product name (optional)','name','','text','placeholder="Printed Lawn Suit"')}${field('Article / design number (optional)','article','','text','placeholder="Leave blank if unavailable"')}<div class="split">${field('Size','size','Unstitched','text','required')}${field('Quantity (suits)','qty',12,'number','min="1" step="1" required')}</div><div class="split">${field('Purchase rate per suit','cost','','number','min="0.01" step="0.01" required')}${field('Selling rate per suit','price','','number','min="0.01" step="0.01" required')}</div>${field('Rack / location','location','Rack A1','text','required')}${button('＋ Add item to delivery','addPurchaseLine()','primary wide')}<div class="note section-gap">Use the batch number, size and rack location to identify stock.</div>${field('Payment to supplier','paid',0,'number','min="0" step="0.01"') }<button class="btn primary wide section-gap" type="submit">Save delivery & add stock</button></div>${purchaseLinesMarkup()}</div></form>`,'',true)};
function addPurchaseLine(){const f=Object.fromEntries(new FormData($('#purchase-form'))),qty=Number(f.qty),cost=Number(f.cost),price=Number(f.price);if(!f.supplier||!f.date||!f.batch||!f.size||!Number.isInteger(qty)||qty<1||!Number.isFinite(cost)||cost<=0||!Number.isFinite(price)||price<=0||!f.location)return toast('Complete supplier, batch, size, quantity, rates and rack location');const line={supplier:f.supplier,date:f.date,batch:f.batch.trim(),name:f.name.trim(),article:f.article.trim(),size:f.size.trim(),qty,cost,price,location:f.location.trim()};const code=purchaseLineCode(line);if(purchaseLines.some(x=>purchaseLineCode(x)===code)||db.products.some(p=>p.code===code))return toast('This supplier batch and size already exists');purchaseLines.push(line);renderPurchaseLines();for(const id of ['batch','name','article'])$('#'+id).value='';$('#qty').value='12';$('#batch').focus();toast('Item added to this delivery')}
function renderPurchaseLines(){const n=$('#purchase-lines');if(n){n.outerHTML=purchaseLinesMarkup();mobileTables($('#overlay'))}}
function removePurchaseLine(index){purchaseLines.splice(index,1);renderPurchaseLines()}
savePurchase=function(){const f=Object.fromEntries(new FormData($('#purchase-form')));if(!purchaseLines.length)return toast('Add at least one item to the delivery');if(!f.supplier||!f.date)return toast('Choose supplier and arrival date');const pmt=Number(f.paid||0),totalCost=sum(purchaseLines.map(x=>x.qty*x.cost));if(!Number.isFinite(pmt)||pmt<0||pmt>totalCost)return toast('Check supplier payment');const seen=new Set(),products=[];for(const x of purchaseLines){const code=purchaseLineCode(x);if(seen.has(code)||db.products.some(p=>p.code===code))return toast('A batch item already exists. Use a new batch number.');seen.add(code);products.push({name:x.name||'Unnamed item · '+x.batch,article:x.article||'',supplier:x.supplier,batch:x.batch,date:x.date,color:'',size:x.size,unit:'Suit',pack:1,cost:x.cost,price:x.price,received:x.qty,stock:x.qty,defect:0,reserved:0,code,location:x.location,tone:db.products.length%2?'pink':'olive',id:uid('P')})}const pur={id:uid('PUR'),supplier:f.supplier,date:f.date,total:totalCost,paid:pmt,note:purchaseLines.map(x=>x.batch+' · '+x.qty+' suits').join(' · ')};for(const [i,p]of products.entries()){db.products.push(p);db.movements.unshift({date:p.date,pid:p.id,qty:p.received,reason:pur.id})}db.purchases.unshift(pur);persist('Received '+products.length+' stock items');purchaseLines=[];closeModal();render();toast('Delivery saved. Stock added successfully')};
function returnRate(sale,item){const gr=sum(sale.items.map(i=>i.qty*i.price));return roundMoney(item.price*(gr?1-sale.discount/gr:1))}
function availableReturnQty(pid,customerId){const sold=sum(db.sales.filter(s=>s.customer===customerId).flatMap(s=>s.items.filter(i=>i.pid===pid).map(i=>i.qty)));const used=sum(db.returns.filter(r=>r.customer===customerId).flatMap(r=>r.items.filter(i=>i.pid===pid).map(i=>i.qty)))+sum(db.sales.filter(s=>s.customer===customerId&&s.returnsApplied).flatMap(s=>s.returnsApplied.filter(i=>i.pid===pid).map(i=>i.qty)));const draft=saleReturnLines.filter(x=>x.pid===pid).reduce((a,x)=>a+x.qty,0);return sold-used-draft}
function findReturnByCode(code){const q=String(code||'').trim().toLowerCase();if(!q||!customer)return null;for(const s of db.sales.filter(s=>s.customer===customer)){const item=s.items.find(i=>{const p=product(i.pid);return p&&p.code.toLowerCase()===q&&availableReturnQty(p.id,customer)>0});if(item){const p=product(item.pid);return {sale:s,item,p,remaining:availableReturnQty(p.id,customer),rate:returnRate(s,item)}}}return null}
function saleReturnMarkup(){return `<div class="sale-return-box"><div class="flex between"><strong>Return item from this customer</strong>${badge(saleReturnLines.length+' returns')}</div><p class="sub">Make the bill first, then enter the item code. The original rate will be deducted.</p><div class="split"><div class="field"><label for="sale-return-code">Item code</label><input id="sale-return-code" value="${esc(saleReturnCode)}" placeholder="Scan or type product code" oninput="saleReturnCode=this.value" onkeydown="if(event.key==='Enter'){event.preventDefault();addSaleReturnByCode()}"></div><div class="field"><label for="sale-return-qty">Quantity</label><input id="sale-return-qty" type="number" min="1" step="1" value="1"></div></div><div class="split"><div class="field"><label for="sale-return-condition">Condition</label><select id="sale-return-condition"><option value="sellable">Sellable stock</option><option value="defective">Defective / quarantine</option></select></div>${button('Add return','addSaleReturnByCode()','small primary')}</div>${saleReturnLines.map((x,n)=>{const p=product(x.pid);return `<div class="return-draft-line"><span><strong>${esc(p.name)}</strong><small>${esc(p.code)} · ${x.qty} × ${money(x.price)}</small></span><strong>− ${money(x.qty*x.price)}</strong><button type="button" class="textbtn danger" onclick="removeSaleReturn(${n})">✕</button></div>`}).join('')}</div>`}
function addSaleReturnByCode(){if(!customer)return toast('Choose this customer first');const match=findReturnByCode(saleReturnCode);const qty=Number($('#sale-return-qty').value||1);if(!match)return toast('This code was not found in this customer\'s previous bills');if(!Number.isInteger(qty)||qty<1||qty>match.remaining)return toast('Return quantity is greater than the remaining sold quantity');const condition=$('#sale-return-condition').value;saleReturnLines.push({pid:match.p.id,qty,price:match.rate,sourceSale:match.sale.id,condition});cart.push({pid:match.p.id,qty,price:-match.rate,isReturn:true,returnOf:match.sale.id});saleReturnCode='';render();toast('Return added at original rate')}
function removeSaleReturn(index){const target=saleReturnLines[index];const cartIndex=cart.findIndex(x=>x.isReturn&&x.pid===target.pid&&x.returnOf===target.sourceSale&&x.qty===target.qty&&x.price===-target.price);if(cartIndex>=0)cart.splice(cartIndex,1);saleReturnLines.splice(index,1);render()}
const saleViewBeforeReturn=saleView;
saleView=function(){let html=saleViewBeforeReturn();html=html.replace('<div class="summary-row"><span>Subtotal</span>',saleReturnMarkup()+'<div class="summary-row"><span>Subtotal</span>');return html.replace(/cart\.splice\((\d+),1\);render\(\)/g,'removeCartLine($1)')};
function removeCartLine(index){if(cart[index]?.isReturn){const n=saleReturnLines.findIndex(x=>x.pid===cart[index].pid&&x.sourceSale===cart[index].returnOf&&x.qty===cart[index].qty&&x.price===-cart[index].price);if(n>=0)saleReturnLines.splice(n,1)}cart.splice(index,1);render()}
const previousAddEntry=addEntry;
addEntry=function(){if(!entryProduct)return toast('Search and choose an item first');const qty=Number($('#entry-qty').value),price=Number($('#entry-price').value),p=product(entryProduct),existing=cart.find(i=>i.pid===p.id&&!i.isReturn);if(!Number.isInteger(qty)||qty<1||!Number.isFinite(price)||price<0)return toast('Check quantity and price');if(qty+(existing?.qty||0)>p.stock-p.reserved+orderReservation(p.id))return toast('Not enough available stock');if(existing&&existing.price!==price)return toast('This batch is already in the cart. Use Edit to change its price.');if(existing)existing.qty+=qty;else cart.push({pid:p.id,qty,price});entryProduct='';entryQuery='';render();$('#item-search').focus();toast('Item added to cart')};
const previousEditCartEntry=editCartEntry;
editCartEntry=function(n){if(cart[n]?.isReturn)return toast('Remove this return line and add it again');previousEditCartEntry(n)};
const previousChooseCustomer=chooseCustomer;
chooseCustomer=function(id){if(saleReturnLines.length&&id!==customer)return toast('Remove return items before changing customer');previousChooseCustomer(id)};
const previousResetWithReturns=resetCart;
resetCart=function(){previousResetWithReturns();saleReturnLines=[];saleReturnCode=''};
validateCart=function(){if(!cart.length){toast('Add an item first');return false}if(total()<0){toast('Returned amount cannot exceed this bill');return false}if(discount>gross()){toast('Discount exceeds the bill. Update discount.');return false}if(paid>total()){toast('Payment cannot exceed bill total');return false}if(!customer&&paid<total()){toast('Choose a customer for a credit sale');return false}if(customer&&paid<total()&&!dueDate){toast('Choose the payment due date');return false}for(const i of cart){if(i.isReturn)continue;const p=product(i.pid);if(i.qty>p.stock-p.reserved+orderReservation(p.id)){toast('Stock changed. Check '+p.name);return false}}return true};
saveSale=function(){if(!saleReturnLines.length)return previousWorkflowSaleSave();tender=readTender('sale');if(!validTender(tender))return;if(tenderTotal(tender)>total())return toast('Combined payment exceeds the bill');if(padNumber.trim()&&db.sales.some(s=>s.padNumber?.toLowerCase()===padNumber.trim().toLowerCase()))return toast('This pad invoice number already exists');if(tender.cheque&&!customer)return toast('Choose a customer for cheque tracking');paid=roundMoney(tender.cash+tender.bank);method=tender.bank?'Split':'Cash';if(!validateCart())return;const id='INV-'+(Math.max(1052,...db.sales.map(s=>Number(s.id.split('-')[1])||0))+1),normal=cart.filter(i=>!i.isReturn),applied=saleReturnLines.map(x=>({...x})),s={id,customer,date:today(),dueDate,items:structuredClone(normal),returnsApplied:applied,discount,total:total(),paid,method,padNumber:padNumber.trim(),contact:{phone:$('#sale-phone').value,address:$('#sale-address').value},tender:structuredClone(tender)};for(const i of normal){const p=product(i.pid);p.stock-=i.qty;db.movements.unshift({date:today(),pid:p.id,qty:-i.qty,reason:s.id})}for(const x of applied){const p=product(x.pid);if(x.condition==='defective'){p.defect+=x.qty;db.claims.unshift({id:uid('CLM')+'-'+p.id,supplier:p.supplier,pid:p.id,qty:x.qty,amount:x.qty*p.cost,status:'Pending',date:today(),return:s.id,dispatched:false})}else p.stock+=x.qty;db.movements.unshift({date:today(),pid:p.id,qty:x.condition==='defective'?0:x.qty,reason:s.id+' · return'})}db.sales.unshift(s);if(tender.cheque)db.cheques.unshift({id:uid('CHQ'),sale:s.id,party:s.customer,type:'customers',amount:tender.cheque,number:tender.number,bank:tender.bankName,date:tender.date,status:'Pending',created:today()});persist('Saved '+s.id+' with '+applied.length+' returned items');resetCart();render();receipt(s.id,true)};
const previousReceiptWithReturn=receipt;
const purchaseFormWithLinesBeforeCheque=purchaseForm,purchaseSaveWithLinesBeforeCheque=savePurchase;
purchaseForm=function(){purchaseFormWithLinesBeforeCheque();const form=$('#purchase-form');if(form){form.innerHTML=form.innerHTML.replace(field('Payment to supplier','paid',0,'number','min="0" step="0.01"'),'<h3 class="section-gap">Payment to supplier</h3>'+tenderFields('purchase'))}};
savePurchase=function(){const t=readTender('purchase');if(!validTender(t))return;const totalCost=sum(purchaseLines.map(x=>x.qty*x.cost));if(tenderTotal(t)>totalCost)return toast('Combined supplier payment exceeds stock cost');const form=$('#purchase-form');if(form&&!form.innerHTML.includes('purchase-paid-hidden'))form.innerHTML+='<input id="purchase-paid-hidden" name="paid" type="hidden">';if($('#purchase-paid-hidden'))$('#purchase-paid-hidden').value=roundMoney(t.cash+t.bank);const before=db.purchases.length;purchaseSaveWithLinesBeforeCheque();if(db.purchases.length===before)return;const pur=db.purchases[0];pur.tender=structuredClone(t);pur.paymentStatus=t.cheque?'Cheque pending':'Paid at receiving';if(t.cheque){db.cheques.unshift({id:uid('CHQ'),type:'suppliers',party:pur.supplier,amount:t.cheque,number:t.number,bank:t.bankName,date:t.date,status:'Pending',created:pur.date,reference:'Stock delivery '+pur.id});persist('Supplier cheque issued for '+pur.id);render();toast('Delivery saved. Cheque added to register')}};
receipt=function(id,success=false){previousReceiptWithReturn(id,success);const s=db.sales.find(x=>x.id===id),el=$('.receipt');if(s?.returnsApplied?.length&&el)el.insertAdjacentHTML('beforeend',`<hr><p><strong>Returned items deducted</strong><br>${s.returnsApplied.map(x=>{const p=product(x.pid);return esc(p.name)+' · '+x.qty+' × '+money(x.price)+' = −'+money(x.qty*x.price)}).join('<br>')}</p>`) }
tenderFields=function(prefix='sale'){const t=prefix==='sale'?tender:{cash:0,bank:0,cheque:0,number:'',bankName:'',date:''},chequeLabel=prefix==='account'?'Cheque received from customer':'Cheque amount',open=t.cheque>0||prefix==='account';return `<div class="payment-grid">${[['cash','Cash'],['bank','Bank transfer'],['cheque',chequeLabel]].map(([k,l])=>`<div class="field"><label for="${prefix}-${k}">${l}</label><input id="${prefix}-${k}" type="number" min="0" step="0.01" value="${t[k]}" oninput="${prefix==='sale'?'updateTender()':''}"></div>`).join('')}</div><details ${open?'open':''} id="${prefix}-cheque-details"><summary>Cheque details: number, bank and date</summary><div class="split">${field('Cheque number',prefix+'-number',t.number,'text',prefix==='account'?'required':'')}${field('Bank name',prefix+'-bankName',t.bankName,'text',prefix==='account'?'required':'')}${field('Cheque date',prefix+'-date',t.date,'date',prefix==='account'?'required':'')}</div><p class="sub">This cheque will be linked to the selected customer and appear in the Cheque Register until cleared.</p></details>`};
render();
